window.GRIM_PARTS["details-85"]=[{"id":"g0047","name":"圣彼得药酒","category":"guides","subcategory":"游戏内生存提示","summary":"提前饮用圣彼得药酒，在受致命伤害时，可以救您的命。","image":"assets/images/aa3545c55b646.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"提前饮用圣彼得药酒，在受致命伤害时，可以救您的命。"}],"related":[]},{"id":"g0048","name":"地下城陷阱","category":"guides","subcategory":"游戏内生存提示","summary":"在地下城，要小心！粗心跑入陷阱，可以使您中毒，使您失去行动能力，或减缓您的速度。","image":"","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"在地下城，要小心！粗心跑入陷阱，可以使您中毒，使您失去行动能力，或减缓您的速度。"}],"related":[]},{"id":"g0049","name":"城堡加成","category":"guides","subcategory":"游戏内生存提示","summary":"每次获得城堡升级，您将获得加成，可以用来更快制造资源、建造新建筑。","image":"","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"每次获得城堡升级，您将获得加成，可以用来更快制造资源、建造新建筑。"}],"related":[]},{"id":"g0050","name":"护盾","category":"guides","subcategory":"游戏内生存提示","summary":"护盾增加护甲的级别，使用它可以防御敌人带来的损失。","image":"assets/images/a3fda7740be92.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"护盾增加护甲的级别，使用它可以防御敌人带来的损失。"}],"related":[]},{"id":"g0051","name":"炼金桌","category":"guides","subcategory":"游戏内生存提示","summary":"通过炼金术可以学会创造出受商人高度重视的黄金。","image":"assets/images/a39ed011b44bd.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"通过炼金术可以学会创造出受商人高度重视的黄金。"}],"related":[]},{"id":"g0052","name":"炼金之金","category":"guides","subcategory":"游戏内生存提示","summary":"炼金术黄金可以用于交换独特武器以及最稀有的技能书籍。","image":"assets/images/af65a68ded08c.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"炼金术黄金可以用于交换独特武器以及最稀有的技能书籍。"}],"related":[]},{"id":"g0053","name":"砍伐桦木","category":"guides","subcategory":"游戏内生存提示","summary":"桦树生长在河流以北的土地上。","image":"assets/images/a6094d44b11d1.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"桦树生长在河流以北的土地上。"}],"related":[]},{"id":"g0054","name":"开采铁矿","category":"guides","subcategory":"游戏内生存提示","summary":"铁矿可以在河流以北的土地上开采。","image":"assets/images/ace03b0b14884.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"铁矿可以在河流以北的土地上开采。"}],"related":[]},{"id":"g0055","name":"北方之地","category":"guides","subcategory":"游戏内生存提示","summary":"只能骑着骏马到达北方之地。没有这样的马就无法在北方生存。","image":"assets/images/afb2a78731a98.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"只能骑着骏马到达北方之地。没有这样的马就无法在北方生存。"}],"related":[]},{"id":"g0056","name":"击晕","category":"guides","subcategory":"游戏内生存提示","summary":"被击晕的角色在短时间内不能移动、攻击或使用技能或物品。","image":"assets/images/af7d74a6b020f.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"被击晕的角色在短时间内不能移动、攻击或使用技能或物品。"}],"related":[]},{"id":"g0057","name":"马交易","category":"guides","subcategory":"游戏内生存提示","summary":"游商那面可以拿你的马换其他毛色和等级的马。少量毛色的马具有加大饱食度。","image":"assets/images/afb2a78731a98.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"游商那面可以拿你的马换其他毛色和等级的马。少量毛色的马具有加大饱食度。"}],"related":[]},{"id":"g0058","name":"换马","category":"guides","subcategory":"游戏内生存提示","summary":"如果您想要拿您的马换新的，请访问骑马游商的场所。步行访问游商时，换马功能无效。","image":"assets/images/afb2a78731a98.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"如果您想要拿您的马换新的，请访问骑马游商的场所。步行访问游商时，换马功能无效。"}],"related":[]},{"id":"g0059","name":"表情","category":"guides","subcategory":"游戏内生存提示","summary":"您可以在游戏中表示您的心情。直接点击人物查看表情符号菜单。","image":"assets/images/a014f47734396.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"您可以在游戏中表示您的心情。直接点击人物查看表情符号菜单。"}],"related":[]},{"id":"g0060","name":"外貌改变","category":"guides","subcategory":"游戏内生存提示","summary":"需要改变您人物的外貌和性别，请在您的家乡场景时点击设置旁边的改变面貌按钮。","image":"assets/images/a057334ce9221.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"需要改变您人物的外貌和性别，请在您的家乡场景时点击设置旁边的改变面貌按钮。"}],"related":[]},{"id":"g0061","name":"下雨","category":"guides","subcategory":"游戏内生存提示","summary":"下雨时会影响移动速度，但同时会增加经验值、亚麻纤维，浆果和蘑菇。","image":"","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"下雨时会影响移动速度，但同时会增加经验值、亚麻纤维，浆果和蘑菇。"}],"related":[]},{"id":"g0062","name":"宠物","category":"guides","subcategory":"游戏内生存提示","summary":"除了尖牙齿以外，每一个宠物有自己的技能。宠物的少见性越高，他的技能越多。","image":"assets/images/a986c48333bd7.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"除了尖牙齿以外，每一个宠物有自己的技能。宠物的少见性越高，他的技能越多。"}],"related":[]},{"id":"g0063","name":"获得小宠物","category":"guides","subcategory":"游戏内生存提示","summary":"你可以在场景寻找，或前往商店购买，或在成年个体交配时获得宠物幼崽。","image":"assets/images/a0f3113d1139f.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"你可以在场景寻找，或前往商店购买，或在成年个体交配时获得宠物幼崽。"}],"related":[]},{"id":"g0064","name":"恐狼等级","category":"guides","subcategory":"游戏内生存提示","summary":"有足够的食物情况下小恐狼长得很快，但是为提升宠物的等级，他需要和你一起战斗。恐狼的最高等级取决于他的少见性。","image":"assets/images/a937f9fdf93ac.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"有足够的食物情况下小恐狼长得很快，但是为提升宠物的等级，他需要和你一起战斗。恐狼的最高等级取决于他的少见性。"}],"related":[]},{"id":"g0065","name":"疲劳","category":"guides","subcategory":"游戏内生存提示","summary":"如果你的恐狼不再攻击敌人，有可能它只是累了。请把它送回棚里或投喂一些恐狼零食以便恢复力量。","image":"assets/images/a986c48333bd7.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"如果你的恐狼不再攻击敌人，有可能它只是累了。请把它送回棚里或投喂一些恐狼零食以便恢复力量。"}],"related":[]},{"id":"g0066","name":"交配","category":"guides","subcategory":"游戏内生存提示","summary":"在棚中交配后，公母兽种都会返回瘟疫之地，但其幼崽有可能比其父母更稀有。","image":"assets/images/a7ea4f6efdb7f.webp","stats":[{"label":"收录提示","value":2}],"sections":[{"title":"提示 1","text":"在棚中交配后，公母兽种都会返回瘟疫之地，但其幼崽有可能比其父母更稀有。"},{"title":"提示 2","text":"只有同等少见性并达到4级的宠物才能相互交配。"}],"related":[]},{"id":"g0067","name":"宠物命令","category":"guides","subcategory":"游戏内生存提示","summary":"点击宠物打开命令菜单，选择你要下的命令。","image":"assets/images/a986c48333bd7.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"点击宠物打开命令菜单，选择你要下的命令。"}],"related":[]},{"id":"g0068","name":"棚","category":"guides","subcategory":"游戏内生存提示","summary":"棚分4个等级。随着等级越高，你可以养越多的宠物，但每一次改良你需要获得相应的改良图纸。","image":"assets/images/a9245e4e899e9.webp","stats":[{"label":"收录提示","value":2}],"sections":[{"title":"提示 1","text":"棚分4个等级。随着等级越高，你可以养越多的宠物，但每一次改良你需要获得相应的改良图纸。"},{"title":"提示 2","text":"别忘了把食物和水留在棚里。饥饿的宠物有可能会变得没力气。"}],"related":[]},{"id":"g0069","name":"宠物技能","category":"guides","subcategory":"游戏内生存提示","summary":"为让宠物的技能有效，必须带他跟你一起走或者下令他保护城堡。部分技能只有伙伴宠物才有。","image":"assets/images/a53c223993ced.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"为让宠物的技能有效，必须带他跟你一起走或者下令他保护城堡。部分技能只有伙伴宠物才有。"}],"related":[]},{"id":"g0070","name":"毒菇","category":"guides","subcategory":"游戏内生存提示","summary":"尽量别吃那些垃圾：如果你呕吐，水和食物指数会降低。","image":"assets/images/a4fd822993975.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"尽量别吃那些垃圾：如果你呕吐，水和食物指数会降低。"}],"related":[]},{"id":"g0071","name":"贪财旧货商","category":"guides","subcategory":"游戏内生存提示","summary":"北方之地有一句话说，如果你碰到了贪财旧货商你就走运了。但远远不是每一个人都有机会能见到他。","image":"","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"北方之地有一句话说，如果你碰到了贪财旧货商你就走运了。但远远不是每一个人都有机会能见到他。"}],"related":[]},{"id":"g0072","name":"叛徒地下墓穴","category":"guides","subcategory":"游戏内生存提示","summary":"在旅行中，你可能会发现一条通往地下墓穴的路。奖励在等着成功从墓穴中活着出来的人。","image":"assets/images/af933d5de2de9.webp","stats":[{"label":"收录提示","value":3}],"sections":[{"title":"提示 1","text":"在旅行中，你可能会发现一条通往地下墓穴的路。奖励在等着成功从墓穴中活着出来的人。"},{"title":"提示 2","text":"地下墓穴的每一层都有好几波敌人，打败他们就可以进入下一层。"},{"title":"提示 3","text":"每次战斗结束后，你都可以选择离开地下墓穴。但是你完成的楼层越多，退出时获得的宝藏就越多！"}],"related":[]},{"id":"g0073","name":"你的骑士团","category":"guides","subcategory":"游戏内生存提示","summary":"加入已有的骑士团，或创建自己的骑士团！突袭魔王、与其他骑士团作战并攻占新的领土：这些精彩内容在等着你，流亡者！","image":"assets/images/adc88c8f58c5c.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"加入已有的骑士团，或创建自己的骑士团！突袭魔王、与其他骑士团作战并攻占新的领土：这些精彩内容在等着你，流亡者！"}],"related":[]},{"id":"g0074","name":"邀请你的朋友！","category":"guides","subcategory":"游戏内生存提示","summary":"你可以通过聊天器邀请你的朋友一起玩《Grim Soul》！","image":"assets/images/a8f26a83ba0b3.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"你可以通过聊天器邀请你的朋友一起玩《Grim Soul》！"}],"related":[]},{"id":"g0075","name":"伟大养母艾莎","category":"guides","subcategory":"游戏内生存提示","summary":"在失去生活中所有有价值的东西以后，艾莎向死亡发信誓。他会以新的面貌临近死亡之夜。","image":"assets/images/a708165616e9f.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"在失去生活中所有有价值的东西以后，艾莎向死亡发信誓。他会以新的面貌临近死亡之夜。"}],"related":[]},{"id":"g0076","name":"艾莎的死亡","category":"guides","subcategory":"游戏内生存提示","summary":"艾莎的死亡引起无名之神的注意。夜游神来得更平凡，但同时找到夜晚地窖的机率也提升。","image":"assets/images/a3aa0f52103c9.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"艾莎的死亡引起无名之神的注意。夜游神来得更平凡，但同时找到夜晚地窖的机率也提升。"}],"related":[]},{"id":"g0077","name":"繁殖者","category":"guides","subcategory":"游戏内生存提示","summary":"如果你想训练你的恐狼获得新的技能，你要找繁殖者，经常在漫游商人的马车旁边能看到他。","image":"assets/images/af72a7c82672f.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"如果你想训练你的恐狼获得新的技能，你要找繁殖者，经常在漫游商人的马车旁边能看到他。"}],"related":[]},{"id":"g0078","name":"流亡者统计","category":"guides","subcategory":"游戏内生存提示","summary":"点击环球地图上的统计标志可以了解你的获胜和失败历史，以及你在瘟疫之地所有访问的地方的历史。","image":"assets/images/a0ccd14603874.webp","stats":[{"label":"收录提示","value":1}],"sections":[{"title":"提示 1","text":"点击环球地图上的统计标志可以了解你的获胜和失败历史，以及你在瘟疫之地所有访问的地方的历史。"}],"related":[]}];
